const today = new Date();
const results = [];

for (const item of $input.all()) {
  const d = item.json;
  const consent = String(d['수신동의여부'] || '').trim().toUpperCase();
  const alreadySent = String(d['재방문유도발송여부'] || '').trim();
  const lastVisit = String(d['마지막방문일'] || '').trim();
  const email = String(d['이메일'] || '').trim();
  const phone = String(d['전화번호'] || '').trim();

  if (consent !== 'Y') continue;
  if (alreadySent !== '') continue;
  if (!email && !phone) continue;
  if (!lastVisit) continue;

  const visitDate = new Date(lastVisit);
  const diffMs = today.getTime() - visitDate.getTime();
  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

  if (diffDays < 179 || diffDays > 181) continue;

  results.push({ json: { ...d, diffDays } });
}

return results;

